-- Same page authority as syncSlidePageCount; only the explicit frozen poll
-- discriminator changes Engage timing. Existing RSS/row behavior stays exact.
create function private.sync_slide_page_count_v1(p_slide jsonb) returns integer
language sql immutable security invoker set search_path='' as $function$
 select case
  when p_slide->>'family'='engage' and p_slide#>'{poll,optionsPerPage}'='4'::jsonb
   then greatest(1,ceil(pg_catalog.jsonb_array_length(p_slide#>'{poll,options}')::numeric/4)::integer)
  when p_slide->>'family'='rss'
   then greatest(1,pg_catalog.jsonb_array_length(p_slide->'news'))
  else greatest(1,ceil(pg_catalog.jsonb_array_length(p_slide->'rows')::numeric/(p_slide->>'rowsPerPage')::integer)::integer)
 end;
$function$;

create or replace function private.assert_studio_document(p_tenant_id uuid,p_orientation text,p_width integer,p_height integer,p_document jsonb,p_referenced_asset_ids uuid[]) returns void
language plpgsql stable security definer set search_path='' as $$
declare
 slide jsonb:=p_document->'syncPresentation';
 legacy jsonb:=p_document;
 refs uuid[];
 synthetic jsonb;
 pages integer;
 duration_ms integer;
begin
 if p_document?'syncPresentation' then
  if p_document?'sitesPresentation' or p_document->'elements' is distinct from '[]'::jsonb
   or pg_catalog.pg_column_size(p_document)>524288
  then raise exception 'Sync document composition invalid' using errcode='23514';end if;
  perform private.assert_sync_slide_v1(p_tenant_id,slide);
  if length(btrim(slide->>'name')) not between 1 and 120
  then raise exception 'Sync document name invalid' using errcode='23514';end if;
  if slide->>'orientation' is distinct from p_document#>>'{artboard,orientation}'
  then raise exception 'Sync document orientation invalid' using errcode='23514';end if;
  pages:=private.sync_slide_page_count_v1(slide);
  if coalesce(p_document#>>'{motion,durationMs}','')!~'^[0-9]{1,6}$'
  then raise exception 'Sync document duration invalid' using errcode='23514';end if;
  duration_ms:=(p_document#>>'{motion,durationMs}')::integer;
  if duration_ms<pages*3000 or duration_ms>120000 or(pages>1 and p_document#>>'{motion,enabled}' is distinct from 'true')
  then raise exception 'Sync document duration invalid' using errcode='23514';end if;
  if slide#>>'{style,motion}' in('rustig','dynamisch') and p_document#>>'{motion,enabled}' is distinct from 'true'
  then raise exception 'Sync animated document requires video' using errcode='23514';end if;
  select coalesce(array_agg(distinct(ref->>'mediaAssetId')::uuid order by(ref->>'mediaAssetId')::uuid),'{}'::uuid[])
   into refs from private.sites_asset_references_v1(slide) ref where ref->>'kind'='tenant';
  if refs is distinct from private.normalize_studio_asset_ids(p_referenced_asset_ids)
  then raise exception 'Sync tenant manifest mismatch' using errcode='23514';end if;
  select coalesce(jsonb_agg(jsonb_build_object('type','image','mediaAssetId',asset_id)),'[]'::jsonb)
   into synthetic from unnest(refs) asset_id;
  legacy:=jsonb_set(jsonb_set(p_document-'syncPresentation','{elements}',synthetic),'{motion,durationMs}',to_jsonb(least(30000,duration_ms)));
 end if;
 -- Existing project lifecycle, active tenant, AAL2/capability, asset ownership,
 -- CAS revisions and command receipts remain in the original writers.
 perform private.assert_studio_document_before_sync_v1(p_tenant_id,p_orientation,p_width,p_height,legacy,p_referenced_asset_ids);
end;$$;

create or replace function private.freeze_sync_studio_release_item_v1()
 returns trigger language plpgsql security definer set search_path='' as $$
declare source_document jsonb;source_checksum text;source_count integer;
 saved_duration integer;page_count integer;
begin
 -- Caller-provided presentation/timing is never trusted or persisted.
 new.sync_studio_presentation_json:=null;new.sync_studio_duration_ms:=null;
 select count(*) into source_count from public.studio_exports export
 where export.tenant_id=new.tenant_id and export.media_asset_id=new.media_asset_id;
 if source_count=0 then return new;end if;
 if source_count<>1 then raise exception 'Studio export identity is ambiguous' using errcode='23514';end if;
 select revision.document_json,export.checksum_sha256 into source_document,source_checksum
 from public.studio_exports export join public.studio_revisions revision
  on revision.tenant_id=export.tenant_id and revision.project_id=export.project_id and revision.id=export.revision_id
 where export.tenant_id=new.tenant_id and export.media_asset_id=new.media_asset_id;
 if source_document is null or source_checksum is distinct from new.checksum_sha256 then
  raise exception 'Studio export checksum does not match the release' using errcode='23514';end if;
 if not(source_document?'syncPresentation') then return new;end if;
 perform private.assert_sync_slide_v1(new.tenant_id,source_document->'syncPresentation');
 if source_document?'sitesPresentation' then raise exception 'Sync document composition invalid' using errcode='23514';end if;
 saved_duration:=(source_document#>>'{motion,durationMs}')::integer;
 page_count:=private.sync_slide_page_count_v1(source_document->'syncPresentation');
 if saved_duration is null or saved_duration not between 3000 and 120000 or saved_duration < 3000*page_count
  or new.duration_seconds*1000 < saved_duration then
  raise exception 'Sync release duration does not cover every saved page' using errcode='23514';end if;
 if new.trim_start_seconds>0 or (new.trim_end_seconds is not null and new.trim_end_seconds*1000<saved_duration) then
  raise exception 'Sync release trim does not cover every saved page' using errcode='23514';end if;
 new.sync_studio_presentation_json:=source_document->'syncPresentation';
 new.sync_studio_duration_ms:=saved_duration;
 return new;
end;$$;

revoke all on function private.sync_slide_schema_v1(),private.sync_dynamic_configuration_schema_v1(),
 private.sync_slide_page_count_v1(jsonb),private.assert_studio_document(uuid,text,integer,integer,jsonb,uuid[]),
 private.freeze_sync_studio_release_item_v1() from public,anon,authenticated,service_role;
comment on function private.sync_slide_page_count_v1(jsonb) is
 'Frozen Sync page count: legacy polls unchanged; explicit four-option Engage pages retain every answer in the complete immutable binary and release.';
